/**
 * Markdown renderer wrapper using `marked`.
 * Converts Markdown text to HTML for rendering in the dashboard.
 *
 * Callers: summary-view (long_summary), transcription-view (descriptions,
 * captions, summaries) and events-list (captions) — all render model- or
 * plugin-generated markdown, e.g. tables appended to long_summary.
 *
 * Security note: This renders trusted content generated by our own plugins
 * (not user input). For user-generated content, add DOMPurify sanitization.
 *
 * Robust table rendering: marked v18 silently drops a GFM table (renders it as
 * paragraph text with <br>) when the header column count !== delimiter column
 * count (n.length !== s.length guard inside the table tokenizer). This happens
 * when the model emits a malformed delimiter row (e.g., fewer cells than the
 * header).  normalizeMarkdown() detects this and pads the delimiter row so
 * marked never silently drops a table.
 */

import { marked } from "marked";
import katex from "katex";
import "katex/dist/katex.min.css";

/**
 * Configure marked: enable GitHub-flavored markdown, line breaks.
 * Module-level side effect: mutates marked's global options at import time
 * so every renderMarkdown caller shares this behavior.
 */
marked.setOptions({
  gfm: true,
  breaks: true,
});

/**
 * LaTeX math support (KaTeX): models occasionally emit LaTeX embedded in
 * Markdown — e.g. "$\rightarrow$" for an arrow in narrative-arc summaries.
 * Inline `$...$` is only treated as math when the content contains a LaTeX
 * command (a backslash sequence), so plain text with currency amounts like
 * "$5 und $10" stays untouched. Block math uses `$$...$$`.
 */
marked.use({
  extensions: [
    {
      name: "blockMath",
      level: "block",
      start(src: string) {
        const idx = src.indexOf("$$");
        return idx >= 0 ? idx : undefined;
      },
      tokenizer(src: string) {
        const match = /^\$\$([\s\S]+?)\$\$/.exec(src);
        return match ? { type: "blockMath", raw: match[0], text: match[1].trim() } : undefined;
      },
      renderer(token) {
        return katex.renderToString((token as unknown as { text: string }).text, {
          throwOnError: false,
          displayMode: true,
        });
      },
    },
    {
      name: "inlineMath",
      level: "inline",
      start(src: string) {
        const idx = src.indexOf("$");
        return idx >= 0 ? idx : undefined;
      },
      tokenizer(src: string) {
        const match = /^\$([^$\n]*\\[a-zA-Z]+[^$\n]*)\$/.exec(src);
        return match ? { type: "inlineMath", raw: match[0], text: match[1] } : undefined;
      },
      renderer(token) {
        return katex.renderToString((token as unknown as { text: string }).text, { throwOnError: false });
      },
    },
  ],
});

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Count the number of column cells in a markdown table row string.
 * Strips leading/trailing pipes and empty cells (from adjacent ||) so that
 *   | col1 | col2 |     → 2 cells
 *   | | col1 | col2    → 2 cells  (empty leading cell ignored)
 *   | col1 || col2 |    → 2 cells  (empty middle cell ignored)
 */
function countColumns(row: string): number {
  const stripped = row.replace(/^\s*\|\s*/, "").replace(/\s*\|\s*$/, "");
  if (!stripped) return 0;
  return stripped.split("|").filter((c) => c.trim() !== "").length;
}

/**
 * Returns true if a line looks like a GFM table delimiter row:
 *   | --- | --- |  (with optional : for alignment)
 * Detects the first-dash group after a leading pipe.
 */
function isDelimiterRow(line: string): boolean {
  const trimmed = line.trim();
  if (!trimmed.startsWith("|")) return false;
  const inner = trimmed.replace(/^\s*\|\s*/, "").replace(/\s*\|\s*$/, "");
  // Each cell must contain at least one dash, optional leading/trailing colon
  const cells = inner.split("|");
  return cells.every((cell) => /^\s*:?\s*-[\s-]*:?\s*$/.test(cell));
}

/**
 * Pad a delimiter row so it has exactly `n` cells matching the header column
 * count.  Each cell becomes ` --- ` (left-aligned) except the last cell which
 * gets ` ---:` (right-aligned) to preserve the right-aligned confidence column
 * convention from the prompt template.
 *
 * Examples (n=3):
 *   | --- |           → | --- | --- | ---: |
 *   | --- | --- |     → | --- | --- | ---: |
 *   | --- | --- | --- | → | --- | --- | ---: |   (unchanged)
 *
 * The delimiter must have EXACTLY n cells (same as header) for marked's
 * n.length === s.length guard to pass.  This function is the only place we
 * need to normalize; body rows are handled by marked's Y(o, header.length)
 * which pads/truncates automatically.
 */
function padDelimiterRow(line: string, n: number): string {
  const trimmed = line.trim();
  const leadingPipe = trimmed.startsWith("|") ? "| " : "";
  const trailingPipe = trimmed.endsWith("|") ? " |" : "";

  // Build n cells: all but last are left-aligned, last is right-aligned (confidence)
  const cells: string[] = [];
  for (let i = 0; i < n - 1; i++) {
    cells.push("---");
  }
  cells.push("---:"); // right-aligned for the last (numeric) column

  return `${leadingPipe}${cells.join(" | ")}${trailingPipe}`;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Split lines where a heading or paragraph is glued to a table start on the
 * SAME line — a frequent model emission ("# Visuelle Artefakte | Artefakt | …"
 * or "Versand. | # Visuelle Artefakte | …"). marked only tokenizes a GFM table
 * at a block start, so the glued prefix turns the whole table into paragraph
 * text. Rule: a non-table line whose first `|` is followed by a table-ish
 * remainder (containing another `|`) is split into prefix + blank line + the
 * table row starting at that `|`. Lines already starting with `|` and fenced
 * code blocks are left untouched.
 */
function splitGluedTableStarts(lines: string[]): string[] {
  const out: string[] = [];
  let inFence = false;
  for (const line of lines) {
    if (/^\s*```/.test(line)) {
      inFence = !inFence;
      out.push(line);
      continue;
    }
    if (inFence) {
      out.push(line);
      continue;
    }
    const trimmed = line.trim();
    if (trimmed.startsWith("|")) {
      out.push(line);
      continue;
    }
    const pipeIdx = line.indexOf("|");
    const prefix = pipeIdx > 0 ? line.slice(0, pipeIdx).trimEnd() : "";
    const rest = pipeIdx >= 0 ? line.slice(pipeIdx + 1) : "";
    if (!prefix.trim() || !rest.includes("|") || !rest.trim()) {
      out.push(line);
      continue;
    }
    out.push(prefix, "", `|${rest}`);
  }
  return out;
}

/**
 * Normalize a markdown string so that every GFM table has the same number of
 * column cells in its delimiter row as in its header row.
 *
 * marked v18 silently drops (paragraph-renders) any table where
 * header.length !== delimiter.length.  This function repairs such tables so
 * marked never silently drops a table regardless of how the model emitted it.
 *
 * Algorithm: first split heading/paragraph lines glued to a table start
 * (splitGluedTableStarts); then walk line-by-line and whenever a `|`-prefixed
 * header row is followed by a `|`-prefixed delimiter row with a different
 * cell count, replace the delimiter row with a padded one that matches the
 * header.
 *
 * Isomorphic — no side effects, no external dependencies.
 */
export function normalizeMarkdown(md: string): string {
  const lines = splitGluedTableStarts(md.split("\n"));
  const result: string[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    result.push(line);

    // Skip if this line doesn't look like a table header row
    const trimmed = line.trim();
    if (!trimmed.startsWith("|")) continue;

    // Look at the next non-empty line
    let j = i + 1;
    while (j < lines.length && lines[j].trim() === "") j++;
    if (j >= lines.length) break;

    const nextLine = lines[j];
    if (!isDelimiterRow(nextLine)) continue;

    const headerCols = countColumns(line);
    const delimiterCols = countColumns(nextLine);

    if (headerCols !== delimiterCols) {
      // Replace the delimiter row in result with the padded version
      result[result.length - 1] = padDelimiterRow(nextLine, headerCols);
      // Also update the source array so the next iteration skips past it
      lines[j] = padDelimiterRow(nextLine, headerCols);
    }
  }

  return result.join("\n");
}

/**
 * Converts a Markdown string to HTML.
 * Returns an empty string for null/undefined input.
 */
export function renderMarkdown(md: string | null | undefined): string {
  if (!md) return "";
  const normalized = normalizeMarkdown(md);
  return marked.parse(normalized, { async: false }) as string;
}

/**
 * Inline variant for single-line fields (titles, labels): no wrapping <p>,
 * so the result is valid inside headings and spans. Supports the same LaTeX
 * math extension as renderMarkdown.
 */
export function renderInlineMarkdown(md: string | null | undefined): string {
  if (!md) return "";
  return marked.parseInline(normalizeMarkdown(md), { async: false }) as string;
}
